/* =========================================================
   COMPLETE OPERATORS DASHBOARD - Lesson 3 Capstone
   Uses: Arithmetic, Assignment, Comparison, Logical, ??, ?., Ternary
========================================================= */

const TOTAL_LESSONS = 10;
const XP_PER_LESSON = 50;

// Simulated Firebase data - could be null, string, number, missing
let firebaseData = {
  xp: "120", // String from Firestore!
  coins: null, // Null - missing
  progress: { javascript: 2 }, // Nested
  profile: { coins: 30 } // Fallback
};

let localData = {
  completed: "2" // String from localStorage!
};

// Safe getters with Number(), ??, ?., || - your dashboard pattern
function getSafeXP(data) {
  return Number(data.xp ?? data.profile?.xp ?? 0); // ?? and ?. and Number()
}

function getSafeCoins(data) {
  return Number(data.coins ?? data.profile?.coins ?? 0);
}

function getSafeCompleted(firebase, local) {
  let completed = firebase.progress?.javascript ?? local.completed ?? 0; // Optional chaining and nullish
  return Math.min(TOTAL_LESSONS, Math.max(0, Number(completed) || 0)); // Math.min, Math.max, Number, ||
}

let xp = getSafeXP(firebaseData); // 120 number (string converted)
let coins = getSafeCoins(firebaseData); // 30 from profile fallback
let completed = getSafeCompleted(firebaseData, localData); // 2 number (string converted)

console.log(`Initial: XP=${xp} (${typeof xp}), Coins=${coins}, Completed=${completed} (${typeof completed})`);

// Progress calculation - arithmetic operators
let percent = Math.round((completed / TOTAL_LESSONS) * 100); // / * Math.round
let nextLesson = completed + 1; // +
let remaining = TOTAL_LESSONS - completed; // -
console.log(`Progress: ${completed}/${TOTAL_LESSONS} = ${percent}% - Next: ${nextLesson}, Remaining: ${remaining}`);

// Status with comparison operators
function getStatus(lessonId) {
  if (lessonId <= completed) return "completed"; // <=
  if (lessonId === nextLesson) return "current"; // ===
  return "locked"; // > implied
}

// Check all lessons status
for (let i = 1; i <= 5; i++) {
  let status = getStatus(i);
  let badge = status === "completed" ? "✅" : status === "current" ? "▶" : "🔒"; // Ternary
  console.log(`Lesson ${i}: ${status} ${badge}`);
}

// Auth and back button with logical operators
