  console.log(`✅ Authenticated: ${user.uid}`);
}

if (!user) { // ! NOT
  console.log("❌ No user - redirect to login");
} else {
  console.log("✅ User exists - show course");
}

if (referrer && referrer.includes(origin)) { // && short-circuit
  console.log("✅ Referrer valid - can history.back()");
}

// Complete lesson with assignment operators
function completeLesson(lessonId) {
  console.log(`\n--- Completing Lesson ${lessonId} ---`);
  let status = getStatus(lessonId);

  if (status === "locked") {
    console.warn(`🔒 Locked! Need ${nextLesson} first`);
    return;
  }

  if (status === "completed") {
    console.log(`✅ Already completed`);
    return;
  }

  // Assignment shortcuts - +=
  completed += 1;
  xp += XP_PER_LESSON;
  coins += 10;

  // Recalculate with arithmetic
  percent = Math.round((completed / TOTAL_LESSONS) * 100);
  nextLesson = completed + 1;

  console.log(`🎉 Completed! XP: ${xp}, Coins: ${coins}, Progress: ${percent}%`);
}

completeLesson(3);
completeLesson(5); // Locked
completeLesson(4);

console.log("\n=== FINAL ===");
console.log(`XP: ${xp}, Coins: ${coins}, Completed: ${completed}/${TOTAL_LESSONS} (${percent}%)`);
console.log(`Next lesson: ${nextLesson}`);

